function declarationStyle(a, b) { return a + b; }
const expressionStyle = function(a, b) { return a + b; };
const arrowStyle = (a, b) => a + b;

// Все три работают одинаково при вызове:
console.log(declarationStyle(2, 3)); // 5
console.log(expressionStyle(2, 3));  // 5
console.log(arrowStyle(2, 3));      // 5

const createUser = (name, age) => ({
    name,
    age,
    greet() {
        return `Привет, я ${name}, мне ${age}`;
    }
});

const user = createUser("Анна", 25);
console.log(user.greet()); // "Привет, я Анна, мне 25"

